// dotnet/decompiler/util/char_info.hpp -- .NET's character classification (System.Char: IsLetterOrDigit, IsDigit, IsControl, IsWhiteSpace,
// IsSurrogate, GetUnicodeCategory) over UTF-16 code units, and the UTF-8 / UTF-16 conversions the port's text goes through. ILSpy decides
// how to escape names and strings by these rules, so the port classifies exactly as .NET does: the categories are .NET's own table
// (char_categories.inc, generated by testdata/oracle/NetText).
//
//     is_letter_or_digit(u'x');                 // true
//     std::u16string s = utf16("Größe");        // .NET's string of the UTF-8 text
//     utf8(s) == "Größe";
#pragma once

#include <cstdint>
#include <string>
#include <string_view>

namespace cb::dotnet::decompiler::util {

// System.Globalization.UnicodeCategory.
enum class UnicodeCategory : std::uint8_t {
    UppercaseLetter, LowercaseLetter, TitlecaseLetter, ModifierLetter, OtherLetter, NonSpacingMark, SpacingCombiningMark, EnclosingMark,
    DecimalDigitNumber, LetterNumber, OtherNumber, SpaceSeparator, LineSeparator, ParagraphSeparator, Control, Format, Surrogate, PrivateUse,
    ConnectorPunctuation, DashPunctuation, OpenPunctuation, ClosePunctuation, InitialQuotePunctuation, FinalQuotePunctuation,
    OtherPunctuation, MathSymbol, CurrencySymbol, ModifierSymbol, OtherSymbol, OtherNotAssigned,
};

UnicodeCategory get_unicode_category(char16_t c);
bool is_letter(char16_t c);
bool is_digit(char16_t c);
bool is_letter_or_digit(char16_t c);
bool is_control(char16_t c);
bool is_white_space(char16_t c);
constexpr bool is_surrogate(char16_t c) { return c >= 0xD800 && c <= 0xDFFF; }
constexpr bool is_high_surrogate(char16_t c) { return c >= 0xD800 && c <= 0xDBFF; }
constexpr bool is_low_surrogate(char16_t c) { return c >= 0xDC00 && c <= 0xDFFF; }

// UTF-8 as .NET decodes it (an invalid sequence is U+FFFD), and UTF-16 back to UTF-8 (a lone surrogate is written as its three-byte form,
// so that it survives the round trip).
std::u16string utf16(std::string_view utf8);
std::string utf8(std::u16string_view utf16);

}  // namespace cb::dotnet::decompiler::util
